#include "web_server.h"

#include <stdbool.h>
#include <string.h>
#include <stdlib.h>
#include "freertos/FreeRTOS.h"
#include "freertos/semphr.h"
#include "esp_log.h"
#include "esp_http_server.h"

static const char *TAG = "web_server";
static const size_t WS_TEXT_MAX_LEN = 64;

/* Embedded HTML page (generated by CMake EMBED_FILES) */
extern const uint8_t radar_page_html_start[] asm("_binary_radar_page_html_start");
extern const uint8_t radar_page_html_end[]   asm("_binary_radar_page_html_end");

static httpd_handle_t s_server = NULL;
static SemaphoreHandle_t s_ws_mutex = NULL;
static bool s_ws_work_queued = false;
static char s_ws_latest[64];

/* ------------------------------------------------------------------ */
/*  HTTP GET /  – serve the radar HTML page                            */
/* ------------------------------------------------------------------ */
static esp_err_t root_get_handler(httpd_req_t *req)
{
    size_t html_len = radar_page_html_end - radar_page_html_start;
    httpd_resp_set_type(req, "text/html");
    httpd_resp_set_hdr(req, "Content-Encoding", "identity");
    httpd_resp_send(req, (const char *)radar_page_html_start, html_len);
    return ESP_OK;
}

static const httpd_uri_t uri_root = {
    .uri      = "/",
    .method   = HTTP_GET,
    .handler  = root_get_handler,
    .user_ctx = NULL,
};

/* ------------------------------------------------------------------ */
/*  WebSocket /ws                                                       */
/* ------------------------------------------------------------------ */
static esp_err_t ws_handler(httpd_req_t *req)
{
    if (req->method == HTTP_GET) {
        /* Handshake – nothing to do, httpd handles it */
        ESP_LOGI(TAG, "WebSocket client connected, fd=%d",
                 httpd_req_to_sockfd(req));
        return ESP_OK;
    }

    /* Receive frame (keep connection alive) */
    httpd_ws_frame_t ws_pkt;
    uint8_t buf[128] = {0};
    memset(&ws_pkt, 0, sizeof(ws_pkt));
    ws_pkt.payload = buf;
    ws_pkt.type    = HTTPD_WS_TYPE_TEXT;

    esp_err_t ret = httpd_ws_recv_frame(req, &ws_pkt, sizeof(buf) - 1);
    if (ret != ESP_OK) {
        ESP_LOGW(TAG, "ws recv error: %d", ret);
        return ret;
    }
    return ESP_OK;
}

static const httpd_uri_t uri_ws = {
    .uri          = "/ws",
    .method       = HTTP_GET,
    .handler      = ws_handler,
    .user_ctx     = NULL,
    .is_websocket = true,
};

/* ------------------------------------------------------------------ */
/*  Async send helper (called inside httpd task via httpd_queue_work)  */
/* ------------------------------------------------------------------ */
static void ws_send_cb(void *arg)
{
    (void)arg;

    char data[64];
    data[0] = '\0';

    if (s_ws_mutex == NULL) {
        return;
    }

    if (xSemaphoreTake(s_ws_mutex, portMAX_DELAY) == pdTRUE) {
        strncpy(data, s_ws_latest, sizeof(data) - 1);
        data[sizeof(data) - 1] = '\0';
        s_ws_work_queued = false;
        xSemaphoreGive(s_ws_mutex);
    }

    if (s_server == NULL || data[0] == '\0') {
        return;
    }

    httpd_ws_frame_t pkt = {
        .final   = true,
        .fragmented = false,
        .type    = HTTPD_WS_TYPE_TEXT,
        .payload = (uint8_t *)data,
        .len     = strlen(data),
    };

    size_t clients = 8;
    int fds[8];

    if (httpd_get_client_list(s_server, &clients, fds) != ESP_OK) {
        return;
    }

    for (size_t i = 0; i < clients; i++) {
        if (httpd_ws_get_fd_info(s_server, fds[i]) != HTTPD_WS_CLIENT_WEBSOCKET) {
            continue;
        }

        esp_err_t ret = httpd_ws_send_frame_async(s_server, fds[i], &pkt);
        if (ret != ESP_OK) {
            ESP_LOGW(TAG, "Closing stale WS client fd=%d after send failure", fds[i]);
            httpd_sess_trigger_close(s_server, fds[i]);
        }
    }
}

/* ------------------------------------------------------------------ */
/*  Public broadcast function                                           */
/* ------------------------------------------------------------------ */
void ws_broadcast(const char *data)
{
    if (s_server == NULL || s_ws_mutex == NULL || data == NULL) return;

    bool should_queue = false;

    if (xSemaphoreTake(s_ws_mutex, portMAX_DELAY) == pdTRUE) {
        strncpy(s_ws_latest, data, WS_TEXT_MAX_LEN - 1);
        s_ws_latest[WS_TEXT_MAX_LEN - 1] = '\0';

        if (!s_ws_work_queued) {
            s_ws_work_queued = true;
            should_queue = true;
        }

        xSemaphoreGive(s_ws_mutex);
    }

    if (should_queue && httpd_queue_work(s_server, ws_send_cb, NULL) != ESP_OK) {
        if (xSemaphoreTake(s_ws_mutex, portMAX_DELAY) == pdTRUE) {
            s_ws_work_queued = false;
            xSemaphoreGive(s_ws_mutex);
        }
    }
}

/* ------------------------------------------------------------------ */
/*  Start server                                                        */
/* ------------------------------------------------------------------ */
void web_server_start(void)
{
    httpd_config_t config = HTTPD_DEFAULT_CONFIG();
    config.max_open_sockets = 10;
    config.lru_purge_enable = true;
    config.keep_alive_enable = true;
    config.keep_alive_idle = 30;
    config.keep_alive_interval = 30;
    config.keep_alive_count = 3;

    ESP_LOGI(TAG, "Starting HTTP server on port %d", config.server_port);
    s_ws_mutex = xSemaphoreCreateMutex();
    ESP_ERROR_CHECK(s_ws_mutex != NULL ? ESP_OK : ESP_ERR_NO_MEM);
    ESP_ERROR_CHECK(httpd_start(&s_server, &config));

    httpd_register_uri_handler(s_server, &uri_root);
    httpd_register_uri_handler(s_server, &uri_ws);

    ESP_LOGI(TAG, "HTTP server started. Open http://192.168.4.1 in your browser.");
}
